const form=document.getElementById("sickLeaveForm"),result=document.getElementById("result");form&&form.addEventListener("submit",t=>{t.preventDefault();const e=parseFloat(document.getElementById("income").value)||0,a=parseInt(document.getElementById("days").value,10)||0,n=parseInt(document.getElementById("tenure").value,10)||100,s=parseFloat(document.getElementById("mrot").value)||22440,c=parseFloat(document.getElementById("maxDaily").value)||5674.77;if(e<=0||a<=0||s<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите доход, дни и МРОТ больше нуля.</p>';return}const l=e/730,i=s*24/730,m=Math.min(Math.max(l,i),c),o=m*a*(n/100);result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Средний дневной (скорр.)</span><span class="val">${fmt(m)} ₽</span></div>
        <div class="item"><span>Процент по стажу</span><span class="val">${n}%</span></div>
        <div class="item"><span>Дней</span><span class="val">${a}</span></div>
        <div class="item total"><span>Начислено</span><span class="val">${fmt(o)} ₽</span></div>
      </div>
      <p class="hint" style="margin-top:14px">Средний дневной без ограничений: ${fmt(l)} ₽; минимум по МРОТ: ${fmt(i)} ₽.</p>
    `});function fmt(t){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(t)}
